// 24-S4 acceptance: the catch-up read against PostgreSQL, in a throwaway
// schema (`src/test-support/database.ts`): the operations since a version,
// in order; the snapshot past the log's retention, too far behind or when
// asked; only for a builder who can edit the puzzle. Two tabs' queues on the
// real commit path, catching up from it, converge. Do not edit this file to
// match an implementation.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { Prisma } from '@prisma/client';
import { createGrid, withLetter, type Grid } from '@/engine/grid';
import { serializeGrid, type SerializedGrid } from '@/lib/puzzle-storage';
import { createTestDatabase, type TestDatabase } from '@/test-support/database';
import type { PuzzleContent } from './apply';
import { readOperationsSince } from './catchup';
import { commitPuzzleOperation } from './commit';
import { projectOutbox } from './outbox';
import { OperationQueue } from './queue';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
  await db.client.user.createMany({ data: [
    { id: 'adam', name: 'Adam', email: 'adam@catchup.example.test', displayName: 'Adam' },
    { id: 'jay', name: 'Jay', email: 'jay@catchup.example.test', displayName: 'Jay' },
  ] });
}, 60_000);
afterAll(async () => { await db?.drop(); });

function letters(grid: Grid, entries: Array<[number, number, string]>): Grid {
  return entries.reduce((next, [col, row, letter]) => withLetter(next, { col, row }, letter), grid);
}
const start: PuzzleContent = {
  grid: serializeGrid(letters(createGrid({ cols: 5, rows: 5 }), [[0, 0, 'C'], [1, 0, 'A'], [2, 0, 'T']])),
  hints: {}, title: 'Catch-up', phase: 'grid',
};
async function seed(builderId = 'adam') {
  return (await db.client.puzzle.create({
    data: { builderId, title: start.title, grid: start.grid as unknown as Prisma.InputJsonValue, hints: {}, phase: 'grid' },
  })).id;
}
async function commit(puzzleId: string, body: Record<string, unknown>, options: { now?: Date; retainCount?: number } = {}) {
  const row = await db.client.puzzle.findUniqueOrThrow({ where: { id: puzzleId } });
  const op = { opId: randomUUID(), puzzleId, clientId: 'elsewhere', epoch: row.resetEpoch, baseVersion: row.version, ...body };
  const outcome = await commitPuzzleOperation(db.client, 'adam', op, options);
  return { op, outcome };
}
const write = (col: number, row: number, value: string | null) => ({ kind: 'cells', writes: [{ col, row, value }] });
async function stored(id: string) {
  const row = await db.client.puzzle.findUniqueOrThrow({ where: { id } });
  return {
    content: { grid: row.grid as unknown as SerializedGrid, hints: row.hints as Record<string, string>, title: row.title, phase: row.phase } as PuzzleContent,
    version: row.version, resetEpoch: row.resetEpoch,
  };
}

describe('24-S4-7 the operations since a version', () => {
  it('none when current; otherwise every accepted one after it, in version order, as committed', async () => {
    const id = await seed();
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 0 })).toEqual({ status: 'ops', ops: [] });
    const a = await commit(id, write(0, 1, 'D'));
    await commit(id, { kind: 'lock', word: { col: 0, row: 0, orientation: 'across', length: 3 } });
    // A refused one is in the log too, but isn't an operation to apply.
    expect((await commit(id, write(1, 0, 'O'))).outcome).toMatchObject({ status: 'refused', code: 'locked' });
    const c = await commit(id, { kind: 'title', title: 'Renamed' });
    const result = await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 0 });
    expect(result.status).toBe('ops');
    if (result.status !== 'ops') return;
    expect(result.ops.map((op) => [op.version, op.kind])).toEqual([[1, 'cells'], [2, 'lock'], [3, 'title']]);
    expect(result.ops[0]).toEqual({ ...a.op, version: 1 });
    expect(result.ops[2]).toEqual({ ...c.op, version: 3 });
    const tail = await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 2 });
    expect(tail.status === 'ops' && tail.ops.map((op) => op.version)).toEqual([3]);
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 3 })).toEqual({ status: 'ops', ops: [] });
  });

  it('the snapshot when asked, past the log’s retention, too far behind, or ahead of the puzzle', async () => {
    const id = await seed();
    for (let i = 0; i < 4; i++) await commit(id, write(i, 2, 'XYZW'[i]), { retainCount: 2 });
    const now = await stored(id);
    const snapshot = { status: 'snapshot', ...now };
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: null })).toEqual(snapshot);
    // Versions 1 and 2 were pruned: from 1 the log can't say what came next.
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 1 })).toEqual(snapshot);
    expect((await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 2 })).status).toBe('ops');
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 0 }, { limit: 3 })).toEqual(snapshot);
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 9 })).toEqual(snapshot);
  });

  it("only for a builder who can edit it; malformed input is invalid", async () => {
    const id = await seed('jay');
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: 0 })).toEqual({ status: 'not-found' });
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: id, since: null })).toEqual({ status: 'not-found' });
    expect(await readOperationsSince(db.client, 'adam', { puzzleId: 'missing', since: 0 })).toEqual({ status: 'not-found' });
    for (const input of [null, {}, { puzzleId: id, since: -1 }, { puzzleId: id, since: 1.5 }, { puzzleId: 'a b', since: 0 }]) {
      expect(await readOperationsSince(db.client, 'jay', input)).toEqual({ status: 'invalid' });
    }
  });
});

describe('24-S4-8 two tabs on the commit path converge by catching up', () => {
  it('overlapping and compatible edits, a Start Over and Enter Hints: both tabs end with the server’s puzzle', async () => {
    const id = await seed();
    const tab = (clientId: string) => new OperationQueue(
      { confirmed: { content: start, version: 0, resetEpoch: 0 }, pending: [] },
      { puzzleId: id, clientId, newOpId: randomUUID },
      { send: (op) => commitPuzzleOperation(db.client, 'adam', op), retryDelaysMs: [5] },
    );
    const a = tab('tab-a');
    const b = tab('tab-b');
    const catchUp = async (queue: OperationQueue) => {
      const result = await readOperationsSince(db.client, 'adam', { puzzleId: id, since: queue.outbox.confirmed.version });
      if (result.status === 'ops') expect(queue.catchUp(result.ops)).toBe(false);
      if (result.status === 'snapshot') queue.resync(result);
    };

    // Overlapping: A writes MASKS down column 1, then B writes MAG over its top three cells.
    a.add({ kind: 'cells', writes: [...'MASKS'].map((value, row) => ({ col: 1, row, value })) });
    await a.whenIdle();
    b.add({ kind: 'cells', writes: [...'MAG'].map((value, row) => ({ col: 1, row, value })) });
    // Compatible: each writes its own cell.
    b.add({ kind: 'cells', writes: [{ col: 4, row: 4, value: 'B' }] });
    a.add({ kind: 'cells', writes: [{ col: 3, row: 4, value: 'A' }] });
    await Promise.all([a.whenIdle(), b.whenIdle()]);
    await catchUp(a);
    await catchUp(b);
    let server = await stored(id);
    for (const queue of [a, b]) {
      expect(queue.outbox).toEqual({ confirmed: server, pending: [] });
    }
    const column = (content: PuzzleContent) => content.grid.cells.map((row) => {
      const cell = row[1];
      return cell.kind === 'active' ? cell.letter : '#';
    }).join('');
    expect(column(server.content)).toBe('MAGKS');

    // A starts over; B's edit made before it hears is refused (epoch), and B follows.
    a.add({ kind: 'startOver', keepLockedWords: false });
    await a.whenIdle();
    const late = b.add({ kind: 'cells', writes: [{ col: 0, row: 4, value: 'L' }] });
    expect(await b.settled(late.opId)).toEqual({ status: 'refused', code: 'epoch' });
    await catchUp(b);
    a.add({ kind: 'cells', writes: [...'ABCDE'].map((value, col) => ({ col, row: 0, value })) });
    await a.whenIdle();
    await catchUp(b);
    b.add({ kind: 'enterHints' });
    await b.whenIdle();
    await catchUp(a);
    await catchUp(b);
    server = await stored(id);
    expect(server).toMatchObject({ resetEpoch: 1 });
    expect(server.content.phase).toBe('hints');
    for (const queue of [a, b]) {
      expect(queue.outbox).toEqual({ confirmed: server, pending: [] });
      expect(projectOutbox(queue.outbox).content.phase).toBe('hints');
    }
  });
});
